def eval_threshold(metric='man',threshold=999,tie='keep'):
 hit=tot=0
 for x,y,sep,bg in examples:
  targ=[(i,j,int(x[i,j])) for i in range(x.shape[0]) for j in range(x.shape[1]) if x[i,j] not in (sep,bg)]
  for i in range(x.shape[0]):
   for j in range(x.shape[1]):
    if x[i,j]!=sep:continue
    ds=[]
    for p,q,v in targ:
     d=abs(i-p)+abs(j-q) if metric=='man' else max(abs(i-p),abs(j-q)) if metric=='cheb' else math.sqrt((i-p)**2+(j-q)**2)
     ds.append((d,v))
    dm=min(z[0] for z in ds)
    wins=[v for d,v in ds if abs(d-dm)<1e-8]
    if dm>threshold:pr=sep
    elif tie=='keep' and len(set(wins))>1:pr=sep
    elif tie=='prefer': pr=next((v for v in wins if v in (9,7,6,5)), wins[0])
    else: pr=Counter(wins).most_common(1)[0][0]
    hit+=int(pr==y[i,j]);tot+=1
 return hit
for metric in ('man','cheb','eucl'):
 print(metric,[(th,eval_threshold(metric,th)) for th in range(1,9)])

